{
  const grid = $('#hm-grid'), months = $('#hm-months'), tip = $('#hm-tip'), wrap = $('#c45 .hm-wrap');
  let cells = [], seen = false, spans = [];
  // each month label sits over the middle of the weeks that belong to it
  const days = $('#c45 .hm-days');
  const placeMonths = () => {
    // day labels start on the same line as the first row of the grid
    if (days){ const d = grid.getBoundingClientRect().top - days.getBoundingClientRect().top; if (Math.abs(d) > .5) days.style.marginTop = (parseFloat(getComputedStyle(days).marginTop) + d) + 'px'; }
    const g = grid.getBoundingClientRect().left; $$('span', months).forEach(sp => { const a = cells[+sp.dataset.a * 7], b = cells[+sp.dataset.b * 7]; if (!a || !b) return; const ra = a.getBoundingClientRect(), rb = b.getBoundingClientRect(); sp.style.left = ((ra.left + rb.right) / 2 - g) + 'px'; }); };
  function build(N, animate){
    grid.innerHTML = ''; months.innerHTML = ''; cells = [];
    const from = new Date(TODAY.getFullYear(), TODAY.getMonth() - N, TODAY.getDate());
    // the grid ends on the last complete week, so no single day hangs off the end
    const start = addDays(from, -((from.getDay() + 6) % 7)), thisMonday = addDays(TODAY, -((TODAY.getDay() + 6) % 7) - (TODAY.getDay() === 0 ? 0 : 7));
    const WEEKS = Math.round((thisMonday - start) / 864e5 / 7) + 1, r = rng(40 + N);
    let total = 0; spans = [];
    for (let w = 0; w < WEEKS; w++){
      // a week belongs to the month its Thursday falls in
      const m = addDays(start, w * 7 + 3).getMonth(), last = spans[spans.length - 1];
      if (!last || last.m !== m) spans.push({ m, a:w, b:w, date:addDays(start, w * 7 + 3) }); else last.b = w;
      for (let d = 0; d < 7; d++){
        const date = addDays(start, w * 7 + d), future = date > TODAY;
        const weekend = d >= 5, base = r(); const n = future ? 0 : Math.round(Math.pow(base, weekend ? 2.6 : 1.3) * (weekend ? 5 : 12));
        total += n;
        const lvl = n === 0 ? 0 : n <= 2 ? 1 : n <= 5 ? 2 : n <= 8 ? 3 : 4;
        const c = document.createElement('span'); c.className = 'hm-c l' + lvl; if (future) c.style.visibility = 'hidden';
        c.dataset.t = `${n} task${n === 1 ? '' : 's'} on ${date.toLocaleDateString('en-GB', { weekday:'short', day:'numeric', month:'short' })}`;
        c.dataset.w = w; grid.appendChild(c); cells.push(c);
      }
    }
    // label the N months in range, skipping partial months at either end
    spans.filter(sp => sp.b - sp.a >= 2).slice(-N).forEach(sp => months.insertAdjacentHTML('beforeend', `<span data-a="${sp.a}" data-b="${sp.b}">${sp.date.toLocaleDateString('en-GB', { month:'short' })}</span>`));
    placeMonths(); wrap.scrollLeft = wrap.scrollWidth;
    if (animate) cells.forEach(c => setTimeout(() => c.classList.add('in'), reduce ? 0 : +c.dataset.w * 22 + Math.random() * 50));
    countTo($('#hm-total'), total, { dur:900 });
  }
  addEventListener('resize', placeMonths);
  grid.addEventListener('mouseover', e => { const c = e.target.closest('.hm-c'); if (c) tip.textContent = c.dataset.t; });
  grid.addEventListener('mouseleave', () => { tip.textContent = 'Hover a day'; });
  let range = 6;
  segInit($('#hm-seg'), v => { range = +v; build(range, seen); });
  build(range, false); $('#hm-total').dataset.v = 0; $('#hm-total').textContent = '0';
  whenSeen($('#c45'), () => { seen = true; build(range, true); ambient('c45', 'pop'); });
}
